package io.tenvyr.control.runtime;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.*;
import io.tenvyr.platform.Json;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.Path;
import java.security.SecureRandom;
import java.util.*;

/** One authenticated loopback management process; diagnostics never expose child output. */
public final class OpenCodeManagementSession implements ProviderDiscoveryService.Session {
    private final Process process;private final String base,password;private volatile boolean closed;
    private OpenCodeManagementSession(Process process,int port,String password){this.process=process;this.base="http://127.0.0.1:"+port;this.password=password;drain(process.getInputStream());drain(process.getErrorStream());}
    public static OpenCodeManagementSession start(JsonNode cli,Map<String,String> host){int port;try(ServerSocket socket=new ServerSocket()){socket.bind(new InetSocketAddress("127.0.0.1",0));port=socket.getLocalPort();}catch(IOException e){throw failure("Management port unavailable");}byte[] random=new byte[24];new SecureRandom().nextBytes(random);String password=Base64.getUrlEncoder().withoutPadding().encodeToString(random);ProcessBuilder builder=new ProcessBuilder(Json.text(cli,"command"),"serve","--port",String.valueOf(port),"--hostname","127.0.0.1");if(cli.has("cwd"))builder.directory(Path.of(Json.text(cli,"cwd")).toFile());builder.environment().clear();builder.environment().putAll(ProcessBoundary.environment(cli,host,false));builder.environment().put("OPENCODE_SERVER_USERNAME","opencode");builder.environment().put("OPENCODE_SERVER_PASSWORD",password);OpenCodeManagementSession session;try{Process child=builder.start();child.getOutputStream().close();session=new OpenCodeManagementSession(child,port,password);}catch(IOException e){throw failure("Management executable could not start");}long deadline=System.nanoTime()+10000000000L;try{while(System.nanoTime()<deadline){if(!session.process.isAlive())throw failure("Management process exited before readiness");try{session.providers();return session;}catch(RuntimeFailure e){if(!session.process.isAlive())throw failure("Management process exited before readiness");}try{Thread.sleep(120);}catch(InterruptedException e){Thread.currentThread().interrupt();throw failure("Management startup interrupted");}}throw failure("Management startup timed out");}catch(RuntimeException e){session.close();throw e;}}
    private static void drain(InputStream input){Thread thread=new Thread(()->{try(input){byte[] buffer=new byte[4096];while(input.read(buffer)>=0){}}catch(IOException ignored){}},"tenvyr-management-drain");thread.setDaemon(true);thread.start();}
    private JsonNode call(String path,JsonNode body){if(closed)throw failure("Management session is closed");HttpURLConnection connection=null;long deadline=System.nanoTime()+5000000000L;try{connection=(HttpURLConnection)URI.create(base+path).toURL().openConnection();connection.setInstanceFollowRedirects(false);connection.setConnectTimeout(5000);connection.setReadTimeout(5000);connection.setRequestProperty("Authorization","Basic "+Base64.getEncoder().encodeToString(("opencode:"+password).getBytes(StandardCharsets.UTF_8)));if(body!=null){connection.setRequestMethod("POST");connection.setDoOutput(true);connection.setRequestProperty("Content-Type","application/json");byte[] bytes=Json.stringify(body).getBytes(StandardCharsets.UTF_8);connection.setFixedLengthStreamingMode(bytes.length);try(OutputStream out=connection.getOutputStream()){out.write(bytes);}}int status=connection.getResponseCode();if(status<200||status>=300)throw failure("Management API request failed (HTTP "+status+")");ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(InputStream input=connection.getInputStream()){byte[] buffer=new byte[4096];for(;;){long remaining=(deadline-System.nanoTime())/1000000;if(remaining<=0)throw failure("Management API timed out");connection.setReadTimeout((int)Math.max(1,remaining));int n=input.read(buffer);if(n<0)break;if(bytes.size()+n>262144)throw failure("Management response exceeds the byte bound");bytes.write(buffer,0,n);}}if(bytes.size()==0)return Json.value(null);try{return Json.parse(bytes.toString(StandardCharsets.UTF_8));}catch(Exception e){throw failure("Management response is malformed");}}catch(RuntimeFailure e){throw e;}catch(IOException e){throw failure("Management API is unavailable");}finally{if(connection!=null)connection.disconnect();}}
    public JsonNode providers(){return parseProviderList(call("/provider",null));}
    public JsonNode authMethods(){return parseAuthMethods(call("/provider/auth",null));}
    public JsonNode authorize(String provider,int method){return parseAuthorization(call("/provider/"+provider+"/oauth/authorize",Json.object("method",method)));}
    public boolean completeOauth(String provider,int method,String code){ObjectNode body=Json.object("method",method);if(code!=null)body.put("code",code);JsonNode result=call("/provider/"+provider+"/oauth/callback",body);return result.isBoolean()&&result.asBoolean();}
    public synchronized void close(){if(closed)return;closed=true;ProcessBoundary.terminate(process);}
    public static String providerId(String value){if(value==null||!value.matches("[A-Za-z0-9_.:-]{1,255}"))throw failure("Invalid provider identity");return value;}
    public static ObjectNode parseProviderList(JsonNode raw){if(!raw.isObject()||!raw.path("all").isArray())throw failure("Provider response is malformed");ArrayNode all=Json.array(),connected=Json.array();Set<String> seen=new HashSet<>();for(JsonNode item:raw.path("all")){if(!item.isObject())continue;String id=providerId(Json.text(item,"id",null));if(seen.add(id)){ObjectNode p=Json.object("id",id);if(item.path("name").isTextual()&&item.path("name").asText().length()<=255)p.set("name",item.get("name"));all.add(p);}if(all.size()>=512)break;}seen.clear();if(raw.path("connected").isArray())for(JsonNode item:raw.path("connected")){if(!item.isTextual())throw failure("Provider response is malformed");String id=providerId(item.asText());if(seen.add(id))connected.add(id);if(connected.size()>=512)break;}ObjectNode defaults=Json.object();if(raw.path("default").isObject())raw.path("default").fields().forEachRemaining(e->{if(defaults.size()<64&&e.getValue().isTextual()&&e.getValue().asText().length()<=255)defaults.set(e.getKey(),e.getValue());});return Json.object("all",all,"connected",connected,"default",defaults);}
    public static ObjectNode parseAuthMethods(JsonNode raw){if(!raw.isObject())throw failure("Auth methods response is malformed");ObjectNode result=Json.object();raw.fields().forEachRemaining(e->{if(!e.getKey().matches("[A-Za-z0-9_.:-]{1,255}")||!e.getValue().isArray())return;ArrayNode methods=Json.array();int index=0;for(JsonNode item:e.getValue()){int at=index++;if(!item.isObject())continue;String type=Json.text(item,"type",""),label=Json.text(item,"label","").trim();if(!Set.of("oauth","api").contains(type)||label.isEmpty()||label.length()>255)continue;methods.add(Json.object("methodIndex",at,"type",type,"label",label,"requiresPrompt",item.path("prompts").isArray()&&!item.path("prompts").isEmpty()));if(methods.size()>=32)break;}result.set(e.getKey(),methods);});return result;}
    public static ObjectNode parseAuthorization(JsonNode raw){String url=Json.text(raw,"url",null),method=Json.text(raw,"method",null);try{URI uri=ModelDiscoveryService.validateUrl(url);if(uri.getFragment()!=null||!Set.of("auto","code").contains(method))throw new IllegalArgumentException();}catch(Exception e){throw new RuntimeFailure("INVALID_OAUTH_URL","Invalid OAuth authorization response");}JsonNode instructions=raw.get("instructions");if(instructions!=null&&!instructions.isNull()&&(!instructions.isTextual()||instructions.asText().length()>512))throw failure("OAuth instructions exceed the bound");return Json.object("url",url,"method",method,"instructions",instructions);}
    static RuntimeFailure failure(String message){return new RuntimeFailure("OPENCODE_SERVER_FAILED",message);}
}
